    if y % 100 == 0:
        if y % 400 == 0:
            print("Leap Year")
        else:
            print("Not Leap Year")
    else:
        print("Leap Year")
else:
    print("Not Leap Year")

a, b, c = map(int, input().split())
if a + b <= c or a + c <= b or b + c <= a:
    print("Invalid")
elif a == b == c:
    print("Equilateral")
elif a == b or b == c or a == c:
    print("Isosceles")
else:
    print("Scalene")

